insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000006311', 'Divergente, pois as integrais laterais não são finitas.', 'A integral de $-1$ até $-a$ tende a $-\infty$, enquanto a de $a$ até $1$ tende a $+\infty$. Não se pode cancelar infinitos. O valor principal simétrico é zero, mas a integral imprópria usual não existe.') on conflict do nothing;
